from math import gcd
from typing import Set

def prime_factors(n: int) -> Set[int]:
    f, m, d = set(), n, 2
    while d * d <= m:
        while m % d == 0:
            f.add(d); m //= d
        d += 1
    if m > 1:
        f.add(m)
    return f

def al_mul(d: int, e: int) -> int:
    g = gcd(d, e)
    return d * e // (g * g)

def symm_diff(a: Set[int], b: Set[int]) -> Set[int]:
    return (a - b) | (b - a)

def verify_realization(N: int) -> None:
    """For squarefree N, verify primeFactors(d*e) = primeFactors(d) triangle primeFactors(e)
    and closure (d*e divides N) over all pairs of divisors."""
    divs = [d for d in range(1, N + 1) if N % d == 0]
    ok = all(
        prime_factors(al_mul(d, e)) == symm_diff(prime_factors(d), prime_factors(e))
        and N % al_mul(d, e) == 0
        for d in divs for e in divs
    )
    print(f"N={N}: realization + closure over all {len(divs)}^2 pairs -> {ok}")
    print(f"  6 * 15 = {al_mul(6, 15)}  (shared prime 3 cancels)")

verify_realization(30)

from typing import List

def is_squarefree(n: int) -> bool:
    m, d = n, 2
    while d * d <= m:
        if m % (d * d) == 0:
            return False
        while m % d == 0:
            m //= d
        d += 1
    return True

def omega(n: int) -> int:
    c, m, d = 0, n, 2
    while d * d <= m:
        if m % d == 0:
            c += 1
            while m % d == 0:
                m //= d
        d += 1
    return c + (1 if m > 1 else 0)

def moebius(n: int) -> int:
    if n == 1:
        return 1
    return 0 if not is_squarefree(n) else (-1) ** omega(n)

def parity_report(limit: int) -> List[int]:
    """Confirm mu(N)=1 iff omega(N) even, and list eligible levels."""
    eligible = []
    for N in range(2, limit + 1):
        if is_squarefree(N):
            assert (moebius(N) == 1) == (omega(N) % 2 == 0)
            if moebius(N) == 1:
                eligible.append(N)
    print(f"Eligible squarefree even-omega levels up to {limit}: {eligible}")
    print("Classical genus-zero levels {6, 10, 22} are among them.")
    return eligible

parity_report(40)

